{"command": "cat > /workspace/nodeutil.go <<'GO'
package main

import (
	"fmt"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

func newNullNode() *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"}
}
func newBoolNode(b bool) *yaml.Node {
	v := "false"
	if b {
		v = "true"
	}
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!bool", Value: v}
}
func newIntNode(i int64) *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!int", Value: strconv.FormatInt(i, 10)}
}
func newFloatNode(f float64) *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: strconv.FormatFloat(f, 'g', -1, 64)}
}
func newStrNode(s string) *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: s}
}
func newMapNode() *yaml.Node {
	return &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
}
func newSeqNode() *yaml.Node {
	return &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
}
func newDocNode(content *yaml.Node) *yaml.Node {
	return &yaml.Node{Kind: yaml.DocumentNode, Content: []*yaml.Node{content}}
}

func deepCopy(n *yaml.Node) *yaml.Node {
	if n == nil {
		return nil
	}
	c := &yaml.Node{
		Kind:        n.Kind,
		Style:       n.Style,
		Tag:         n.Tag,
		Value:       n.Value,
		Anchor:      n.Anchor,
		Alias:       n.Alias,
		HeadComment: n.HeadComment,
		LineComment: n.LineComment,
		FootComment: n.FootComment,
		Line:        n.Line,
		Column:      n.Column,
	}
	for _, ch := range n.Content {
		c.Content = append(c.Content, deepCopy(ch))
	}
	return c
}

func isNull(n *yaml.Node) bool {
	if n == nil {
		return true
	}
	if n.Kind == yaml.DocumentNode {
		if len(n.Content) == 0 {
			return true
		}
		return isNull(n.Content[0])
	}
	return n.Tag == "!!null"
}
func isFalse(n *yaml.Node) bool {
	if isNull(n) {
		return true
	}
	u := unwrapDoc(n)
	if u.Tag == "!!bool" && u.Value == "false" {
		return true
	}
	return false
}
func unwrapDoc(n *yaml.Node) *yaml.Node {
	if n == nil {
		return newNullNode()
	}
	if n.Kind == yaml.DocumentNode {
		if len(n.Content) == 0 {
			return newNullNode()
		}
		return n.Content[0]
	}
	return n
}
func unwrapAll(n *yaml.Node) *yaml.Node {
	return unwrapDoc(n)
}

func nodeKindStr(n *yaml.Node) string {
	u := unwrapDoc(n)
	switch u.Kind {
	case yaml.ScalarNode:
		return "scalar"
	case yaml.MappingNode:
		return "map"
	case yaml.SequenceNode:
		return "seq"
	case yaml.AliasNode:
		return "alias"
	case yaml.DocumentNode:
		return "document"
	}
	return "unknown"
}

func scalarString(n *yaml.Node) string {
	u := unwrapDoc(n)
	if u.Kind != yaml.ScalarNode {
		return ""
	}
	return u.Value
}

func toFloat(n *yaml.Node) (float64, bool) {
	u := unwrapDoc(n)
	if u.Tag == "!!int" {
		v, err := strconv.ParseInt(strings.TrimSpace(u.Value), 0, 64)
		if err == nil {
			return float64(v), true
		}
		// try float parse
		f, err2 := strconv.ParseFloat(strings.TrimSpace(u.Value), 64)
		if err2 == nil {
			return f, true
		}
		return 0, false
	}
	if u.Tag == "!!float" {
		f, err := strconv.ParseFloat(strings.TrimSpace(u.Value), 64)
		if err == nil {
			return f, true
		}
		return 0, false
	}
	if u.Tag == "!!str" {
		// try parse?
		f, err := strconv.ParseFloat(strings.TrimSpace(u.Value), 64)
		if err == nil {
			return f, true
		}
		return 0, false
	}
	return 0, false
}
func toInt(n *yaml.Node) (int64, bool) {
	u := unwrapDoc(n)
	if u.Tag == "!!int" {
		v, err := strconv.ParseInt(strings.TrimSpace(u.Value), 0, 64)
		if err == nil {
			return v, true
		}
		return 0, false
	}
	if u.Tag == "!!float" {
		f, err := strconv.ParseFloat(strings.TrimSpace(u.Value), 64)
		if err == nil {
			return int64(f), true
		}
		return 0, false
	}
	return 0, false
}

func nodesEqual(a, b *yaml.Node) bool {
	ua := unwrapDoc(a)
	ub := unwrapDoc(b)
	if ua.Tag != ub.Tag {
		// special: int vs float? compare numerically?
		// For ==, yq does strict? Test: 1 == 1.0? Probably true? Let's do numeric compare if both numbers
		if (ua.Tag == "!!int" || ua.Tag == "!!float") && (ub.Tag == "!!int" || ub.Tag == "!!float") {
			fa, oka := toFloat(ua)
			fb, okb := toFloat(ub)
			if oka && okb {
				return fa == fb
			}
		}
		return false
	}
	switch ua.Kind {
	case yaml.ScalarNode:
		return ua.Value == ub.Value
	case yaml.SequenceNode:
		if len(ua.Content) != len(ub.Content) {
			return false
		}
		for i := range ua.Content {
			if !nodesEqual(ua.Content[i], ub.Content[i]) {
				return false
			}
		}
		return true
	case yaml.MappingNode:
		if len(ua.Content) != len(ub.Content) {
			return false
		}
		// order matters? For ==, order maybe not? Simplify order-sensitive
		for i := 0; i < len(ua.Content); i += 2 {
			k := ua.Content[i].Value
			found := false
			for j := 0; j < len(ub.Content); j += 2 {
				if ub.Content[j].Value == k {
					if !nodesEqual(ua.Content[i+1], ub.Content[j+1]) {
						return false
					}
					found = true
					break
				}
			}
			if !found {
				return false
			}
		}
		return true
	}
	return false
}

func compareNodes(a, b *yaml.Node) (int, error) {
	ua := unwrapDoc(a)
	ub := unwrapDoc(b)
	// numbers?
	if (ua.Tag == "!!int" || ua.Tag == "!!float") && (ub.Tag == "!!int" || ub.Tag == "!!float") {
		fa, _ := toFloat(ua)
		fb, _ := toFloat(ub)
		if fa < fb {
			return -1, nil
		} else if fa > fb {
			return 1, nil
		}
		return 0, nil
	}
	// strings?
	if ua.Tag == "!!str" && ub.Tag == "!!str" {
		if ua.Value < ub.Value {
			return -1, nil
		} else if ua.Value > ub.Value {
			return 1, nil
		}
		return 0, nil
	}
	// fallback string compare?
	if ua.Kind == yaml.ScalarNode && ub.Kind == yaml.ScalarNode {
		if ua.Value < ub.Value {
			return -1, nil
		} else if ua.Value > ub.Value {
			return 1, nil
		}
		return 0, nil
	}
	return 0, fmt.Errorf("cannot compare %s with %s", ua.Tag, ub.Tag)
}

func mapGet(m *yaml.Node, key string) *yaml.Node {
	u := unwrapDoc(m)
	if u.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i < len(u.Content); i += 2 {
		if u.Content[i].Value == key {
			return u.Content[i+1]
		}
	}
	return nil
}
func mapGetNode(m *yaml.Node, keyNode *yaml.Node) *yaml.Node {
	u := unwrapDoc(m)
	kn := unwrapDoc(keyNode)
	if u.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i < len(u.Content); i += 2 {
		if nodesEqual(u.Content[i], kn) {
			return u.Content[i+1]
		}
	}
	return nil
}

func nodeToGo(n *yaml.Node) interface{} {
	u := unwrapDoc(n)
	switch u.Kind {
	case yaml.MappingNode:
		m := make(map[string]interface{})
		// preserve order? use map for now; for JSON we need order? Use map
		for i := 0; i < len(u.Content); i += 2 {
			k := u.Content[i].Value
			m[k] = nodeToGo(u.Content[i+1])
		}
		return m
	case yaml.SequenceNode:
		var arr []interface{}
		for _, c := range u.Content {
			arr = append(arr, nodeToGo(c))
		}
		return arr
	case yaml.ScalarNode:
		switch u.Tag {
		case "!!null":
			return nil
		case "!!bool":
			return u.Value == "true"
		case "!!int":
			// try int
			if v, err := strconv.ParseInt(strings.TrimSpace(u.Value), 0, 64); err == nil {
				return v
			}
			// fallback float?
			if f, err := strconv.ParseFloat(strings.TrimSpace(u.Value), 64); err == nil {
				return f
			}
			return u.Value
		case "!!float":
			if f, err := strconv.ParseFloat(strings.TrimSpace(u.Value), 64); err == nil {
				return f
			}
			return u.Value
		default:
			return u.Value
		}
	case yaml.AliasNode:
		return nil
	}
	return nil
}

func goToNode(v interface{}) *yaml.Node {
	if v == nil {
		return newNullNode()
	}
	switch x := v.(type) {
	case string:
		return newStrNode(x)
	case bool:
		return newBoolNode(x)
	case int:
		return newIntNode(int64(x))
	case int64:
		return newIntNode(x)
	case float64:
		return newFloatNode(x)
	case []interface{}:
		n := newSeqNode()
		for _, e := range x {
			n.Content = append(n.Content, goToNode(e))
		}
		return n
	case map[string]interface{}:
		n := newMapNode()
		for k, val := range x {
			n.Content = append(n.Content, newStrNode(k), goToNode(val))
		}
		return n
	case map[interface{}]interface{}:
		n := newMapNode()
		for k, val := range x {
			ks := fmt.Sprintf("%v", k)
			n.Content = append(n.Content, newStrNode(ks), goToNode(val))
		}
		return n
	default:
		return newStrNode(fmt.Sprintf("%v", v))
	}
}
GO
