func (c *EvalContext) copy() *EvalContext {
	n := &EvalContext{
		Vars: map[string]*yaml.Node{},
		Filename: c.Filename,
		FileIndex: c.FileIndex,
		DocIndex: c.DocIndex,
		StringInterpolation: c.StringInterpolation,
		DisableEnv: c.DisableEnv,
		DisableFile: c.DisableFile,
		Indent: c.Indent,
	}
	for k,v := range c.Vars {
		n.Vars[k]=v
	}
	return n
}

// Lexer
type TokType int
const (
	T_EOF TokType = iota
	T_DOT
	T_DOTDOT
	T_DOTDOTDOT
	T_PIPE
	T_COMMA
	T_SEMI
	T_COLON
	T_LPAREN
	T_RPAREN
	T_LBRACK
	T_RBRACK
	T_LBRACE
	T_RBRACE
	T_QUESTION
	T_AT
	T_DOLLAR
	T_IDENT
	T_STRING
	T_NUMBER
	T_TRUE
	T_FALSE
	T_NULL
	T_OP // generic op: =, ==, !=, >=, <=, >, <, +, -, *, /, %, //, |=, +=, -=, *=, /=, %=
	T_AND
	T_OR
	T_AS
	T_IREDUCE
)

type Token struct {
	Type TokType
	Val string
	Pos int
}

func isAlpha(c byte) bool { return (c>='a'&&c<='z')||(c>='A'&&c<='Z')||c=='_' }
func isDigit(c byte) bool { return c>='0'&&c<='9' }
func isAlnum(c byte) bool { return isAlpha(c)||isDigit(c) }

func lex(input string) ([]Token, error) {
	var toks []Token
	i:=0
	n:=len(input)
	for i<n {
		c:=input[i]
		// whitespace
		if c==' '||c=='\t'||c=='\n'||c=='\r' {
			i++; continue
		}
		// comment
		if c=='#' {
			// skip to end of line
			for i<n && input[i]!='\n' { i++ }
			continue
		}
		// strings
		if c=='"' {
			start:=i
			i++
			var sb strings.Builder
			sb.WriteByte('"')
			for i<n {
				if input[i]=='\\' && i+1<n {
					sb.WriteByte(input[i]); sb.WriteByte(input[i+1]); i+=2; continue
				}
				if input[i]=='"' {
					sb.WriteByte('"'); i++; break
				}
				sb.WriteByte(input[i]); i++
			}
			toks=append(toks, Token{T_STRING, sb.String(), start})
			_ = start
			continue
		}
		if c=='\'' {
			start:=i
			i++
			var sb strings.Builder
			sb.WriteByte('\'')
			for i<n {
				if input[i]=='\'' {
					// check '' escape? In yq single quotes '' is escaped '? For YAML single quotes, '' is '. Handle.
					if i+1<n && input[i+1]=='\'' {
						sb.WriteString("''"); i+=2; continue
					}
					sb.WriteByte('\''); i++; break
				}
				sb.WriteByte(input[i]); i++
			}
			toks=append(toks, Token{T_STRING, sb.String(), start})
			continue
		}
		// numbers (including negative? handle - as op, but numbers can start with digit or .digit? Simplify: digit)
		if isDigit(c) || (c=='.' && i+1<n && isDigit(input[i+1])) {
			start:=i
