	T_FALSE
	T_NULL
	T_OP // generic op: =, ==, !=, >=, <=, >, <, +, -, *, /, %, //, |=, +=, -=, *=, /=, %=
	T_AND
	T_OR
	T_AS
	T_IREDUCE
