type Token struct {
	Type TokType
	Val string
	Pos int
}

func isAlpha(c byte) bool { return (c>='a'&&c<='z')||(c>='A'&&c<='Z')||c=='_' }
func isDigit(c byte) bool { return c>='0'&&c<='9' }
func isAlnum(c byte) bool { return isAlpha(c)||isDigit(c) }

func lex(input string) ([]Token, error) {
	var toks []Token
	i:=0
	n:=len(input)
	for i<n {
		c:=input[i]
		// whitespace
		if c==' '||c=='\t'||c=='\n'||c=='\r' {
			i++; continue
		}
		// comment
		if c=='#' {
			// skip to end of line
			for i<n && input[i]!='\n' { i++ }
			continue
		}
		// strings
		if c=='"' {
			start:=i
			i++
			var sb strings.Builder
			sb.WriteByte('"')
			for i<n {
				if input[i]=='\\' && i+1<n {
					sb.WriteByte(input[i]); sb.WriteByte(input[i+1]); i+=2; continue
				}
				if input[i]=='"' {
					sb.WriteByte('"'); i++; break
				}
				sb.WriteByte(input[i]); i++
			}
			toks=append(toks, Token{T_STRING, sb.String(), start})
			_ = start
			continue
		}
		if c=='\'' {
			start:=i
			i++
			var sb strings.Builder
			sb.WriteByte('\'')
			for i<n {
				if input[i]=='\'' {
					// check '' escape? In yq single quotes '' is escaped '? For YAML single quotes, '' is '. Handle.
					if i+1<n && input[i+1]=='\'' {
						sb.WriteString("''"); i+=2; continue
					}
					sb.WriteByte('\''); i++; break
				}
				sb.WriteByte(input[i]); i++
			}
			toks=append(toks, Token{T_STRING, sb.String(), start})
			continue
		}
		// numbers (including negative? handle - as op, but numbers can start with digit or .digit? Simplify: digit)
		if isDigit(c) || (c=='.' && i+1<n && isDigit(input[i+1])) {
			start:=i
			// hex? 0x...
			if c=='0' && i+1<n && (input[i+1]=='x'||input[i+1]=='X') {
				i+=2
				for i<n && (isDigit(input[i])||(input[i]>='a'&&input[i]<='f')||(input[i]>='A'&&input[i]<='F')) { i++ }
				toks=append(toks, Token{T_NUMBER, input[start:i], start})
				continue
			}
			for i<n && isDigit(input[i]) { i++ }
			if i<n && input[i]=='.' {
				// check if next is digit? If not, don't consume '.' (it's dot op). But we already know c is digit, so '.' could be decimal or path? e.g., "1.a"? Unlikely. Handle: if next after '.' is digit, consume as float, else leave '.'.
				if i+1<n && isDigit(input[i+1]) {
					i++
					for i<n && isDigit(input[i]) { i++ }
				}
			}
			if i<n && (input[i]=='e'||input[i]=='E') {
				j:=i+1
				if j<n && (input[j]=='+'||input[j]=='-') { j++ }
				k:=j
				for k<n && isDigit(input[k]) { k++ }
				if k>j {
					i=k
				}
			}
			toks=append(toks, Token{T_NUMBER, input[start:i], start})
			continue
		}
		// ... , .. , .
		if c=='.' {
			if i+2<n && input[i+1]=='.' && input[i+2]=='.' {
				toks=append(toks, Token{T_DOTDOTDOT, "...", i}); i+=3; continue
			}
			if i+1<n && input[i+1]=='.' {
				toks=append(toks, Token{T_DOTDOT, "..", i}); i+=2; continue
			}
			toks=append(toks, Token{T_DOT, ".", i}); i++; continue
		}
		// $var
		if c=='$' {
			start:=i; i++
			s:=i
			for i<n && (isAlnum(input[i])||input[i]=='_') { i++ }
			if s==i {
				return nil, fmt.Errorf("1:%d: lexer: invalid input text \"$\"", start+1)
			}
			toks=append(toks, Token{T_DOLLAR, input[start:i], start})
			continue
		}
		// @op
		if c=='@' {
			start:=i; i++
			s:=i
			// allow letters, digits, _? e.g., @base64d, @uri, @csv, @json, @yaml, @sh, @tsv, @props? etc. Also @base64d? Check.
			for i<n && (isAlnum(input[i])||input[i]=='_' ) { i++ }
			if s==i {
				return nil, fmt.Errorf("1:%d: lexer: invalid input text \"@\"", start+1)
			}
			toks=append(toks, Token{T_AT, input[start:i], start})
			continue
		}
		// operators: |, |=, //, //=?, /, /, etc.
		if c=='|' {
			if i+1<n && input[i+1]=='=' {
				toks=append(toks, Token{T_OP, "|=", i}); i+=2; continue
			}
			toks=append(toks, Token{T_PIPE, "|", i}); i++; continue
		}
		if c==',' { toks=append(toks, Token{T_COMMA, ",", i}); i++; continue }
		if c==';' { toks=append(toks, Token{T_SEMI, ";", i}); i++; continue }
		if c==':' { toks=append(toks, Token{T_COLON, ":", i}); i++; continue }
		if c=='(' { toks=append(toks, Token{T_LPAREN, "(", i}); i++; continue }
		if c==')' { toks=append(toks, Token{T_RPAREN, ")", i}); i++; continue }
		if c=='[' { toks=append(toks, Token{T_LBRACK, "[", i}); i++; continue }
		if c==']' { toks=append(toks, Token{T_RBRACK, "]", i}); i++; continue }
		if c=='{' { toks=append(toks, Token{T_LBRACE, "{", i}); i++; continue }
		if c=='}' { toks=append(toks, Token{T_RBRACE, "}", i}); i++; continue }
		if c=='?' { toks=append(toks, Token{T_QUESTION, "?", i}); i++; continue }
		if c=='=' {
			if i+1<n && input[i+1]=='=' {
				toks=append(toks, Token{T_OP, "==", i}); i+=2; continue
			}
			toks=append(toks, Token{T_OP, "=", i}); i++; continue
		}
		if c=='!' {
			if i+1<n && input[i+1]=='=' {
				toks=append(toks, Token{T_OP, "!=", i}); i+=2; continue
			}
			return nil, fmt.Errorf("1:%d: lexer: invalid input text %q", i+1, snippet(input,i))
		}
		if c=='>' {
			if i+1<n && input[i+1]=='=' {
				toks=append(toks, Token{T_OP, ">=", i}); i+=2; continue
			}
			toks=append(toks, Token{T_OP, ">", i}); i++; continue
		}
		if c=='<' {
			if i+1<n && input[i+1]=='=' {
				toks=append(toks, Token{T_OP, "<=", i}); i+=2; continue
			}
			toks=append(toks, Token{T_OP, "<", i}); i++; continue
		}
		if c=='+' {
			if i+1<n && input[i+1]=='=' {
				toks=append(toks, Token{T_OP, "+=", i}); i+=2; continue
			}
			toks=append(toks, Token{T_OP, "+", i}); i++; continue
		}
		if c=='-' {
			if i+1<n && input[i+1]=='=' {
				toks=append(toks, Token{T_OP, "-=", i}); i+=2; continue
			}
			toks=append(toks, Token{T_OP, "-", i}); i++; continue
		}
		if c=='*' {
			if i+1<n && input[i+1]=='=' {
				toks=append(toks, Token{T_OP, "*=", i}); i+=2; continue
			}
			toks=append(toks, Token{T_OP, "*", i}); i++; continue
		}
		if c=='/' {
			if i+1<n && input[i+1]=='/' {
				if i+2<n && input[i+2]=='=' {
					toks=append(toks, Token{T_OP, "//=", i}); i+=3; continue
				}
				toks=append(toks, Token{T_OP, "//", i}); i+=2; continue
			}
			if i+1<n && input[i+1]=='=' {
				toks=append(toks, Token{T_OP, "/=", i}); i+=2; continue
			}
			toks=append(toks, Token{T_OP, "/", i}); i++; continue
		}
		if c=='%' {
			if i+1<n && input[i+1]=='=' {
				toks=append(toks, Token{T_OP, "%=", i}); i+=2; continue
			}
			toks=append(toks, Token{T_OP, "%", i}); i++; continue
		}
		// identifiers / keywords
		if isAlpha(c) {
			start:=i
			for i<n && (isAlnum(input[i])||input[i]=='_'||input[i]=='-') { i++ }
			word:=input[start:i]
			switch word {
			case "and":
				toks=append(toks, Token{T_AND, word, start}); continue
			case "or":
				toks=append(toks, Token{T_OR, word, start}); continue
			case "as":
				toks=append(toks, Token{T_AS, word, start}); continue
			case "ireduce":
				toks=append(toks, Token{T_IREDUCE, word, start}); continue
			case "true":
				toks=append(toks, Token{T_TRUE, word, start}); continue
			case "false":
				toks=append(toks, Token{T_FALSE, word, start}); continue
			case "null":
				toks=append(toks, Token{T_NULL, word, start}); continue
			default:
				// check if valid operator name? We need to validate against known functions.
				// If unknown, lexer should error? Original lexer errors for unknown words like "values", "reduce", etc.
				// But words inside strings are ok. Here word is outside.
				// We need to allow any ident that is known; unknown should cause lexer error.
				// However, field names after '.' should be allowed even if unknown? e.g., ".foobar" – foobar is field, not function. Our parser will handle '.' + IDENT as field, not as function. So any IDENT after '.' is ok.
				// For standalone IDENT (function call), only known ones are allowed. But lexer doesn't know context. So we cannot error here.
				// Instead, let parser handle unknown functions as lexer error? Original error is "lexer: invalid input text ..." for unknown like "values" when used as function. How to replicate? The lexer must have list of known tokens and error on unknown.
				// For ".values" – is that allowed? ".values" would be field access "values", should be allowed. While "values" alone as function should error.
				// So lexer should not error yet; parser will error if standalone unknown ident.
				// We'll just emit IDENT.
				toks=append(toks, Token{T_IDENT, word, start}); continue
			}
		}
		return nil, fmt.Errorf("1:%d: lexer: invalid input text %q", i+1, snippet(input,i))
	}
	toks=append(toks, Token{T_EOF, "", n})
	return toks, nil
}

func snippet(s string, pos int) string {
	end:=pos+10
	if end>len(s) { end=len(s) }
	// escape?
	t:=s[pos:end]
	// truncate and add ... if needed?
	if len(t)>10 {
		t=t[:10]
	}
	// need to show as in error: e.g., "values" or "range(3)" etc. Original shows up to ~10 chars + ...?
	// We'll mimic: if remaining len >10, show first 10 + ...? Check examples: 'Error: 1:11: lexer: invalid input text "values"' – input was '{"a":1} | values' – position 11 (1-indexed?) Let's not worry exact.
	return t
}

