func (e *AssignExpr) Eval(input *yaml.Node, ctx *EvalContext) ([]*yaml.Node, error) {
	// Handle different ops
	switch e.Op {
	case "=":
		return evalAssign(input, e.Left, e.Right, ctx, "=")
	case "|=":
		return evalAssign(input, e.Left, e.Right, ctx, "|=")
	case "+=":
		return evalAssign(input, e.Left, e.Right, ctx, "+=")
	case "-=":
		return evalAssign(input, e.Left, e.Right, ctx, "-=")
	case "*=":
		return evalAssign(input, e.Left, e.Right, ctx, "*=")
	default:
		return nil, fmt.Errorf("bad expression, please check expression syntax")
	}
}

