		}
		// sort seq (lexicographically? Numerically? Mixed? Use compareNodes)
		n:=newSeqNode()
		for _,c:=range u.Content { n.Content=append(n.Content, deepCopy(c)) }
		// simple bubble sort using compareNodes
		for i:=0;i<len(n.Content);i++ {
			for j:=i+1;j<len(n.Content);j++ {
				cmp, err:=compareNodes(n.Content[i], n.Content[j])
				if err==nil && cmp>0 {
					n.Content[i], n.Content[j]=n.Content[j], n.Content[i]
				}
			}
		}
		return []*yaml.Node{n}, nil
	case "reverse":
		u:=unwrapDoc(input)
		if u.Kind!=yaml.SequenceNode {
			return nil, fmt.Errorf("node at path [] is not an array (it's a %s)", u.Tag)
		}
		n:=newSeqNode()
		for i:=len(u.Content)-1;i>=0;i-- { n.Content=append(n.Content, deepCopy(u.Content[i])) }
		return []*yaml.Node{n}, nil
	case "unique":
		u:=unwrapDoc(input)
		if u.Kind!=yaml.SequenceNode {
			return nil, fmt.Errorf("only arrays are supported for unique")
		}
		var out []*yaml.Node
		for _,c:=range u.Content {
			found:=false
			for _,o:=range out {
				if nodesEqual(o, c) { found=true; break }
			}
			if !found { out=append(out, deepCopy(c)) }
		}
		n:=newSeqNode(); n.Content=out
		return []*yaml.Node{n}, nil
	case "flatten":
		u:=unwrapDoc(input)
		if u.Kind!=yaml.SequenceNode {
			return nil, fmt.Errorf("only arrays are supported for flatten")
		}
		n:=newSeqNode()
		var rec func(x *yaml.Node)
		rec=func(x *yaml.Node) {
			ux:=unwrapDoc(x)
			if ux.Kind==yaml.SequenceNode {
				for _,c:=range ux.Content { rec(c) }
			} else {
				n.Content=append(n.Content, deepCopy(x))
			}
		}
		for _,c:=range u.Content { rec(c) }
		return []*yaml.Node{n}, nil
	}
	return nil, fmt.Errorf("unknown function %s", name)
}
