func runEvalPerDoc(expr Expr, docs []DocInfo, opts *Options) int {
	// For each doc, eval expr with that doc's content
	type PerDoc struct {
		Results []*yaml.Node
		Info DocInfo
	}
	var all [][]*yaml.Node
	var infos []DocInfo
	hasError:=false
	for _,d:=range docs {
		ctx:=newCtx()
		ctx.StringInterpolation=opts.StringInterpolation
		ctx.DisableEnv=opts.SecurityDisableEnvOps
		ctx.DisableFile=opts.SecurityDisableFileOps
		ctx.Filename=d.Filename; ctx.FileIndex=d.FileIndex; ctx.DocIndex=d.DocIndex
		ctx.Indent=opts.Indent
		var input *yaml.Node
		if d.Node.Kind==yaml.DocumentNode && len(d.Node.Content)>0 {
			input=d.Node.Content[0]
		} else {
			input=d.Node
		}
		// Handle debug-node-info flag? If set, print node info for each result instead of normal?
		vals,err:=expr.Eval(input, ctx)
		if err!=nil {
			// Check for optional? Already handled. Print error and return 1? But for select with no match, vals empty, no error. Good.
			fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
			return 1
		}
		// Handle prettyPrint? If opts.PrettyPrint, clear styles for each val? Actually -P is shorthand for '... style = ""' – applied after eval to all results? Implement as clearing styles.
		if opts.PrettyPrint {
			for _,v:=range vals {
				clearStyles(unwrapDoc(v))
			}
		}
		// Handle debug-node-info? If set, replace vals with debug info? Actually --debug-node-info prints kind/tag/value/line/column for each result? Test showed for '.a' with value 5, output was kind/tag/value/line/column. That's 5 lines? Implement.
		if opts.DebugNodeInfo {
			var dbg []*yaml.Node
			for _,v:=range vals {
				u:=unwrapDoc(v)
				m:=newMapNode()
				kindStr:=""
				switch u.Kind {
				case yaml.ScalarNode: kindStr="ScalarNode"
				case yaml.MappingNode: kindStr="MappingNode"
				case yaml.SequenceNode: kindStr="SequenceNode"
				case yaml.AliasNode: kindStr="AliasNode"
				}
				m.Content=append(m.Content, newStrNode("kind"), newStrNode(kindStr), newStrNode("tag"), newStrNode(u.Tag), newStrNode("value"), newStrNode(u.Value), newStrNode("line"), newIntNode(int64(u.Line)), newStrNode("column"), newIntNode(int64(u.Column)))
				dbg=append(dbg, m)
