func runEvalAllStream(expr Expr, docs []DocInfo, opts *Options) int {
	// Stream evaluation for eval-all: evaluate expr with all docs as stream
	// Simplify: implement via evalStream helper that handles top-level * with selects, etc.
	// For general case, we can try to evaluate expr with each doc and combine? But for select merge, need stream.
	// Detect pattern: 'select(...) * select(...)' – handle specially by evaluating each select across all docs, then merging.
	// More generally, for any binary op (Arith with *), evaluate left and right across all docs (stream) and combine via product?
	// Implement generic stream eval for Arith *, Pipe, Comma, etc.
	// For simplicity, if expr is Arith with *, handle as stream product.
	if arith,ok:=expr.(*ArithExpr); ok && arith.Op=="*" {
		// Evaluate left and right with stream (all docs)
		leftStream:=evalStreamForEA(arith.Left, docs, opts)
		rightStream:=evalStreamForEA(arith.Right, docs, opts)
		// leftStream and rightStream are lists of nodes (each from stream filtering)
		// If either empty, result empty? For select merge, each has 1, product 1. Good.
		// If both have multiple, product? Take first of each? Or cartesian? For merge of 2 files, each has 1, product 1. Good.
		// Implement cartesian product and merge each pair via * (recursive merge)? Actually left and right are already evaluated values (docs), need to merge each pair via mergeMaps? But left/right could be arbitrary exprs, not just selects. For general *, left and right each produce streams, then each pair merged via evalMultiply?
		// Simplify: if leftStream and rightStream each have 1, merge them via evalMultiply and return single.
		// If one empty, return empty (no output) – matches 'e' case where per-doc gives empty, but for 'ea' with 2 docs, leftStream has 1, rightStream has 1, so not empty.
		if len(leftStream)==0||len(rightStream)==0 {
			// No output (empty)
			return outputResults([][]*yaml.Node{}, docs, opts)
		}
		// Cartesian product? For simplicity, if each has 1, merge. If multiple, merge all? E.g., left has 2, right has 2, product 4? Unclear. For merge of N files via ireduce, not here. For select merge with 2 files, each has 1. Good.
		// Take first of each? Or fold all? For 'select(...) * select(...)' with 2 selects, each gives 1, merge to 1. Good.
		// If more, fold?
		acc:=leftStream[0]
		for _,r:=range rightStream {
			merged,err:=evalMultiply(acc, r)
			if err!=nil {
				fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
				return 1
			}
			acc=merged
		}
		// If leftStream has more than 1, need to merge them too? For 'select' with multiple matches? E.g., leftStream could have multiple? For fileIndex==0 with 1 file, left has 1. Good.
		// If left has multiple, merge them first? Actually leftStream from select across all docs could have multiple (e.g., select with no filter gives all). Then acc should be merge of all left + all right? Hmm.
		// For now, merge all left together, then with all right? Let's merge all left into one, then with all right.
		if len(leftStream)>1 {
			tmp:=leftStream[0]
			for _,v:=range leftStream[1:] {
				m,err:=evalMultiply(tmp, v)
				if err!=nil { fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error()); return 1 }
				tmp=m
			}
			acc=tmp
			for _,r:=range rightStream {
				m,err:=evalMultiply(acc, r)
				if err!=nil { fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error()); return 1 }
				acc=m
			}
		}
		return outputResults([][]*yaml.Node{{acc}}, docs, opts)
	}
	// For other exprs, fallback to per-doc (same as eval)? That will give same as eval for simple cases, which matches observed (ea '.' same as e '.'). Good.
	return runEvalPerDoc(expr, docs, opts)
}

func evalStreamForEA(expr Expr, docs []DocInfo, opts *Options) []*yaml.Node {
	var out []*yaml.Node
	for _,d:=range docs {
		ctx:=newCtx()
		ctx.StringInterpolation=opts.StringInterpolation
		ctx.DisableEnv=opts.SecurityDisableEnvOps
		ctx.DisableFile=opts.SecurityDisableFileOps
		ctx.Filename=d.Filename; ctx.FileIndex=d.FileIndex; ctx.DocIndex=d.DocIndex
		var input *yaml.Node
		if d.Node.Kind==yaml.DocumentNode && len(d.Node.Content)>0 {
			input=d.Node.Content[0]
		} else {
			input=d.Node
		}
		vals,err:=expr.Eval(input, ctx)
		if err!=nil { continue }
		out=append(out, vals...)
	}
	return out
}

