			var node *yaml.Node
			if autoParse {
				node=parseAutoValue(val)
			} else {
				node=newStrNode(val)
			}
			m.Content=append(m.Content, newStrNode(h), node)
		}
		seq.Content=append(seq.Content, m)
	}
	// Return as single doc containing seq? Test: csv input gave seq of maps (yaml seq). Good. Wrap in doc.
	return []*yaml.Node{newDocNode(seq)}, nil
