func encodeLuaPerDoc(all [][]*yaml.Node, opts *Options) (string, error) {
	var sb strings.Builder
	prefix:=opts.LuaPrefix
	suffix:=opts.LuaSuffix
	for _,group:=range all {
		for _,res:=range group {
			u:=unwrapDoc(res)
			if opts.LuaGlobals && u.Kind==yaml.MappingNode {
				for i:=0;i<len(u.Content);i+=2 {
					k:=u.Content[i].Value
					v:=encodeLuaValue(u.Content[i+1], 0, opts)
					sb.WriteString(fmt.Sprintf("%s = %s;\n", k, v))
				}
				continue
			}
			s:=encodeLuaValue(u, 0, opts)
			sb.WriteString(prefix + s + suffix)
		}
	}
	return sb.String(), nil
}
func encodeLuaNode(n *yaml.Node, opts *Options) string {
	return encodeLuaValue(n, 0, opts)
}
func encodeLuaValue(n *yaml.Node, indent int, opts *Options) string {
	u:=unwrapDoc(n)
	switch u.Kind {
	case yaml.ScalarNode:
		switch u.Tag {
		case "!!null":
			return "nil"
		case "!!bool":
			return u.Value
		case "!!int", "!!float":
			return u.Value
		default:
			return strconv.Quote(u.Value)
		}
	case yaml.SequenceNode:
		if len(u.Content)==0 {
			return "{}"
		}
		var sb strings.Builder
		sb.WriteString("{\n")
		for _,c:=range u.Content {
			sb.WriteString(strings.Repeat("\t", indent+1))
			sb.WriteString(encodeLuaValue(c, indent+1, opts))
			sb.WriteString(",\n")
		}
		sb.WriteString(strings.Repeat("\t", indent))
		sb.WriteString("}")
		return sb.String()
	case yaml.MappingNode:
		if len(u.Content)==0 {
			return "{}"
		}
		var sb strings.Builder
		sb.WriteString("{\n")
		for i:=0;i<len(u.Content);i+=2 {
			k:=u.Content[i].Value
			v:=encodeLuaValue(u.Content[i+1], indent+1, opts)
			var keyStr string
			if opts.LuaUnquoted {
				keyStr=k
			} else {
				keyStr=fmt.Sprintf("[%s]", strconv.Quote(k))
			}
			sb.WriteString(strings.Repeat("\t", indent+1))
			sb.WriteString(fmt.Sprintf("%s = %s;", keyStr, v))
			sb.WriteString("\n")
		}
		sb.WriteString(strings.Repeat("\t", indent))
		sb.WriteString("}")
		return sb.String()
	}
	return "nil"
}
